function [speed_signals, torque_signals, flux_linkage_signals, current_signals] = mfun_cvc_monitored_signals(fbk_in, ref_in, w_M_ref, p)
%MFUN_CVC_MONITORED_SIGNALS Block Monitored signals of the control system.
%   Generated by motulator_export from the MATLAB port of motulator. The parameters are
%   the fields of the struct p (from the mask, [] as NaN).
fbk = im_observer_outputs_unpack(fbk_in);
ref = im_references_unpack(ref_in);
% Monitored signals
% The currents in estimated rotor flux coordinates
rot = exp(-1i*angle(fbk.psi_R));
speed_signals = [w_M_ref; fbk.w_M];
torque_signals = [ref.tau_M; fbk.tau_M];
flux_linkage_signals = [abs(fbk.psi_s); abs(fbk.psi_R)];
current_signals = [ ...
    real(rot * ref.i_s);
    real(rot * fbk.i_s);
    imag(rot * ref.i_s);
    imag(rot * fbk.i_s)];
end

function s = im_observer_outputs_unpack(u)
%IM_OBSERVER_OUTPUTS_UNPACK Struct of the signal vector u.
s = struct( ...
    'i_s', complex(u(1), u(2)), ...
    'u_s', complex(u(3), u(4)), ...
    'u_s_zoh', complex(u(5), u(6)), ...
    'psi_s', complex(u(7), u(8)), ...
    'psi_R', complex(u(9), u(10)), ...
    'tau_M', u(11), ...
    'w_c', u(12), ...
    'w_s', u(13), ...
    'w_r', u(14), ...
    'w_m', u(15), ...
    'w_M', u(16), ...
    'theta_c', u(17), ...
    'e_o', complex(u(18), u(19)), ...
    'eps', u(20), ...
    'h', u(21));
end

function s = im_references_unpack(u)
%IM_REFERENCES_UNPACK Struct of the signal vector u.
s = struct( ...
    'tau_M', u(1), ...
    'i_s', complex(u(2), u(3)), ...
    'u_s', complex(u(4), u(5)));
end
